function exportRows(){return currentRows.map(r=>({'Território':r.name,[`Votos de referência — ${label('a')}`]:r.a,[`Participação de referência (%) — ${label('a')}`]:r.sa,[`Votos comparados — ${label('b')}`]:r.b,[`Participação comparada (%) — ${label('b')}`]:r.sb,[`${semantics().title} (p.p.)`]:r.delta,'Diferença de votos':r.dv,[`Situação de referência — ${label('a')}`]:TERRITORY_STATUS[r.status_a],[`Situação comparada — ${label('b')}`]:TERRITORY_STATUS[r.status_b]}));}
function download(content,filename,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const rs=exportRows(),heads=Object.keys(rs[0]||{'Território':''}),cell=v=>`"${String(v??'').replace(/"/g,'""')}"`;download('\ufeff'+[heads.map(cell).join(';'),...rs.map(r=>heads.map(h=>cell(r[h])).join(';'))].join('\r\n'),'comparacao-eleitoral.csv','text/csv;charset=utf-8');}
function exportExcel(){const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(exportRows()),'Comparação');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(['a','b'].map(s=>({Candidatura:label(s),Turno:state[s].data?.meta.turno,Recorte:scopeLabel(),Agregação:$('level').selectedOptions[0].textContent}))),'Metadados');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([[semantics().formula],['Participação = votos nominais válidos / total nominal válido do cargo e turno.'],['Bairro do local de votação não identifica residência.'],[$('coverage').textContent],[$('notice').textContent],['Snapshot',catalog.generated_at]]),'Metodologia');XLSX.writeFile(wb,'comparacao-eleitoral.xlsx');}
function exportGeo(){const rs=new Map(currentRows.map(r=>[r.id,r])),features=currentFeatures.map(f=>{const r=rs.get(String(f.properties.id));return {...f,properties:{...f.properties,territorio:r?.name??f.properties.nome,candidatura_referencia:label('a'),candidatura_comparada:label('b'),votos_referencia:r?.a??null,participacao_referencia_pct:r?.sa??null,votos_comparados:r?.b??null,participacao_comparada_pct:r?.sb??null,diferenca_participacao_pp:r?.delta??null,diferenca_votos:r?.dv??null,comparavel:r?.comparable??false,situacao_referencia:TERRITORY_STATUS[r?.status_a||statusFor('a',String(f.properties.id),$('level').value,null)],situacao_comparada:TERRITORY_STATUS[r?.status_b||statusFor('b',String(f.properties.id),$('level').value,null)],definicao_diferenca:semantics().formula}};});download(JSON.stringify({type:'FeatureCollection',snapshot:catalog.generated_at,features}),'comparacao-eleitoral.geojson','application/geo+json');}
async function exportPNG(){const b=$('download-png'),center=maps[activeMap]?.getCenter(),zoom=maps[activeMap]?.getZoom();b.disabled=true;document.body.classList.add('exporting');syncing=true;for(const m of Object.values(maps)){m.invalidateSize({pan:false});m.setView(center,zoom,{animate:false,reset:true});}syncing=false;try{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const canvas=await html2canvas($('map-export'),{backgroundColor:'#f6f8fb',scale:2,useCORS:true});const blob=await new Promise(r=>canvas.toBlob(r));if(blob)download(blob,'mapas-eleitorais.png','image/png');}catch(e){showError(e);}finally{document.body.classList.remove('exporting');b.disabled=false;syncing=true;for(const m of Object.values(maps)){m.invalidateSize({pan:false});if(center)m.setView(center,zoom,{animate:false,reset:true});}syncing=false;activateMap(activeMap);}}
function activateMap(side){const previous=maps[activeMap],center=previous?.getCenter(),zoom=previous?.getZoom();activeMap=side;document.querySelectorAll('.map-card[data-map]').forEach(el=>el.classList.toggle('mobile-active',el.dataset.map===side));document.querySelectorAll('.map-tabs button').forEach(el=>el.setAttribute('aria-selected',String(el.dataset.map===side)));syncing=true;for(const m of Object.values(maps)){m.invalidateSize({pan:false});if(center)m.setView(center,zoom,{animate:false,reset:true});}syncing=false;}
function autoCity(){if(cityCodes().length){$('scope').value='city';$('territory').value='';$('level').value='bairro';}}
async function preset(name){for(const s of ['a','b']){state[s].person=name==='Flávio Valle'?'flavio_valle':'paes';$(`year-${s}`).value=s==='a'?'2024':'2026';$(`turn-${s}`).value='1';}$('scope').value='capital';$('level').value='bairro';$('territory').value='';await Promise.all(['a','b'].map(s=>populateDataset(s,name==='Flávio Valle'?(s==='a'?'13':'7'):(s==='a'?'11':'3'),'60011')));await render();}
async function selectCandidate(side,candidate){
  $(`year-${side}`).value=String(candidate.year);$(`turn-${side}`).value='1';
  state[side].person=null;
  await populateDataset(side,candidate.cargo,candidate.ue);
  const c=state[side].data?.candidates.find(c=>c.id===candidate.candidate);
  if(!c)throw Error('Candidatura indisponível nesta versão dos dados.');
  state[side].candidate=c.id;state[side].person=personId(c,state[side].data.meta)||norm(c.full_name);
  populateCandidates(side);await loadCandidate(side);
  if(candidate.cargo==='13'){$('scope').value=candidate.ue==='60011'?'capital':'municipio';$('municipality').value=candidate.ue;$('level').value='bairro';$('territory').value='';}
  await render();
}
async function initRivals(){
  const rivals=[{year:2018,name:'WILSON WITZEL'},{year:2022,name:'CLÁUDIO CASTRO'},{year:2026,name:'DOUGLAS RUAS'}];
  const candidacies=await Promise.all(rivals.map(async rival=>{
    const dataset=allDatasets.find(d=>d.year===rival.year&&d.cargo==='3'&&d.turno==='1'&&d.ue==='RJ');
    if(!dataset)return null;
    const data=await json(dataset.file),candidate=data.candidates.find(c=>norm(c.name)===norm(rival.name));
    return candidate?{...candidate,year:rival.year,cargo:'3',ue:'RJ',candidate:candidate.id}:null;
  }));
  $('rivals-results').innerHTML=candidacies.map((c,i)=>c?`<article class="card rival-candidate"><p class="rival-election">GOVERNADOR · ${c.year} · 1º TURNO</p><h3>${esc(c.name)}</h3><p class="rivals-note">${esc(c.party)} · Nº ${esc(c.number)} · ${fmt(c.votes)} votos no estado</p><div class="rival-actions"><button class="secondary" data-rival="${i}" data-rival-side="a" aria-label="Selecionar ${esc(c.name)} em ${c.year} como referência">Selecionar referência</button><button class="secondary" data-rival="${i}" data-rival-side="b" aria-label="Selecionar ${esc(c.name)} em ${c.year} como comparado">Selecionar comparado</button></div></article>`:'').join('');
  $('rivals-status').textContent=candidacies.some(c=>!c)?'Algumas candidaturas estão indisponíveis nesta versão dos dados.':'';
  $('rivals-results').addEventListener('click',async event=>{
    const button=event.target.closest('button[data-rival-side]');if(!button)return;
    const c=candidacies[Number(button.dataset.rival)],side=button.dataset.rivalSide;
    const buttons=$('rivals-results').querySelectorAll('button');buttons.forEach(b=>b.disabled=true);
    $('rivals-status').textContent=`Carregando ${c.name} · ${c.year}…`;
    try{await selectCandidate(side,c);$('rivals-status').textContent=`${c.name} · ${c.year} selecionado como ${side==='a'?'referência':'comparado'}.`;}
    catch(e){$('rivals-status').textContent=e.message;}
    finally{buttons.forEach(b=>b.disabled=false);}
  });
}
async function methodology(){
  const [sources,geo,audits,metro]=await Promise.all([json('sources.json'),json('geography-sources.json'),Promise.all(catalog.years.map(y=>json(`audit-${y.year}.json`).catch(()=>({year:y.year,status:'indisponivel'})))),json('metro_geography_sources.json').catch(()=>null)]);
  const electoral=Array.isArray(sources)?sources:Object.values(sources.resources||sources.sources||sources).filter(v=>v&&typeof v==='object');
  const rows=[...electoral,...geo.sources,...(metro?.sources||[])];
  const ma=metro?.audit;$('metro-methodology').innerHTML=ma?`<h2>Bairros metropolitanos e referência territorial</h2><p>${fmt(ma.bairros_validos)} bairros válidos em ${fmt(ma.municipios_com_bairros)} dos ${fmt(ma.municipios_escopo)} municípios metropolitanos. Petrópolis e Paracambi permanecem no nível municipal. A cobertura de votos é calculada por eleição e município, sem confundir área coberta com votos localizados.</p><p>Referência: ${esc(metro.territorial_reference)}. ${fmt(ma.quarentena)} geometrias ficaram em quarentena; há ${fmt(ma.overlap_pairs)} pares de polígonos com sobreposição. Pontos em mais de um bairro permanecem sem atribuição automática.</p><p>A vigência jurídica de algumas malhas permanece sem confirmação, incluindo Queimados em relação à Lei Complementar 100/2023. As classificações mostram a versão da fonte usada e as lacunas efetivas de votação.</p><a href="data/metro_geography_sources.json" download>Baixar manifesto metropolitano</a>`:'';
  const status={verified:'Conferida',verified_zip_crc:'CRC conferido',zip_crc_verified:'CRC conferido',parsed_json:'Estrutura conferida',complete:'Completo',verified_with_version_exclusions:'Conferida com diferenças de versão documentadas',divergences:'Divergências: recortes afetados bloqueados'};
  $('source-table').querySelector('tbody').innerHTML=rows.map(r=>`<tr><td>${esc(r.path||r.file||r.resource_name||r.id||'')}</td><td>${esc(r.generated_at||r.generation||'Não informada')}</td><td>${esc(r.collected_at?.slice(0,10)||'—')}</td><td>${esc(status[r.integrity]||r.integrity||'—')}<br><small>${fmt(r.size_bytes??r.bytes)} bytes</small></td><td><a href="${esc(r.source||r.url||'#')}" target="_blank" rel="noopener">Fonte oficial ↗</a>${r.legal_validity?`<br><small>${esc(r.legal_validity)}</small>`:''}<br><details><summary>SHA256</summary><code style="overflow-wrap:anywhere">${esc(r.sha256||'Não disponível')}</code></details></td></tr>`).join('');
  $('audit-content').innerHTML=`<div class="audit-cards">${audits.map(a=>{const extra=a.unmatched_section_contests||[],excluded=extra.filter(r=>r.excluded_from_current_valid).reduce((n,r)=>n+r.votes,0),unresolved=extra.filter(r=>!r.excluded_from_current_valid).reduce((n,r)=>n+r.votes,0);return `<article class="card audit-card"><strong>${a.year}</strong><p>${a.status==='processed'?'Processado':'Indisponível'}</p><p>Reconciliação: ${esc(status[a.nominal_reconciliation]||a.nominal_reconciliation||'—')}</p><p>Divergências de candidato/zona: ${fmt(a.divergent_candidate_zones)}</p><p>Votos de seção fora do nominal válido atual, com conferência exata: ${fmt(excluded)}</p><p>Votos de seção pendentes de conferência: ${fmt(unresolved)}</p><p>Locais em revisão geográfica: ${fmt(a.pending_geography)}</p><a href="data/audit-${a.year}.json" download>Baixar auditoria por zona</a></article>`;}).join('')}</div>`;
}
async function init(){[catalog,bairros,municipios,people]=await Promise.all([json('catalog.json'),json('bairros-metro.geojson').catch(()=>json('bairros.geojson')),json('municipios.geojson'),json('people.json')]);allDatasets=catalog.years.flatMap(y=>y.datasets);byBairro=Object.fromEntries(bairros.features.flatMap(f=>[[f.properties.id,f.properties],...(f.properties.legacy_id?[[f.properties.legacy_id,f.properties]]:[])]));byMunicipio=Object.fromEntries(municipios.features.map(f=>[f.properties.tse,f.properties]));$('municipality').replaceChildren(...municipios.features.slice().sort((a,b)=>a.properties.nome.localeCompare(b.properties.nome)).map(f=>option(f.properties.tse,f.properties.nome,f.properties.tse==='60011')));$('snapshot').textContent=`Snapshot · ${new Date(catalog.generated_at).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}`;
for(const s of ['a','b']){$(`year-${s}`).replaceChildren(...catalog.years.map(y=>option(y.year,y.year,String(y.year)===(s==='a'?'2024':'2026'))));for(const f of ['year','turn'])$(`${f}-${s}`).addEventListener('change',async()=>{try{await populateDataset(s);autoCity();await render();}catch(e){showError(e);}});$(`dataset-${s}`).addEventListener('change',async()=>{try{await loadDataset(s);autoCity();await render();}catch(e){showError(e);}});$(`search-${s}`).addEventListener('input',()=>populateCandidates(s));$(`candidate-${s}`).addEventListener('change',async()=>{state[s].candidate=$(`candidate-${s}`).value||null;const c=selected(s);if(c)state[s].person=personId(c,state[s].data.meta)||norm(c.full_name);try{await loadCandidate(s);await render();}catch(e){showError(e);}});}
initPSD({fetchIndex:()=>json('psd-candidates.json'),selectCandidate});
$('scope').addEventListener('change',()=>{$('territory').value='';$('level').value=['capital','city','municipio','metro','metro-other'].includes($('scope').value)?'bairro':'municipio';render().catch(showError);});for(const f of ['municipality','level','metric','territory'])$(f).addEventListener('change',()=>{if(['level','municipality'].includes(f))$('territory').value='';render().catch(showError);});document.querySelectorAll('th[data-sort]').forEach(th=>th.addEventListener('click',()=>{const k=th.dataset.sort;sortDesc=k===sortKey?!sortDesc:k!=='name';sortKey=k;table();}));document.querySelectorAll('.nav').forEach(button=>button.addEventListener('click',async()=>{document.querySelectorAll('.nav,.view').forEach(el=>el.classList.remove('active'));button.classList.add('active');$(button.dataset.view).classList.add('active');location.hash=button.dataset.view;try{if(button.dataset.view==='metodologia')await methodology();else Object.values(maps).forEach(m=>m.invalidateSize());}catch(e){showError(e);}}));document.querySelectorAll('.map-tabs button').forEach(b=>b.addEventListener('click',()=>activateMap(b.dataset.map)));$('preset-paes').addEventListener('click',()=>preset('Eduardo Paes').catch(showError));$('preset-flavio').addEventListener('click',()=>preset('Flávio Valle').catch(showError));$('download-csv').addEventListener('click',exportCSV);$('download-xlsx').addEventListener('click',exportExcel);$('download-geo').addEventListener('click',exportGeo);$('download-png').addEventListener('click',exportPNG);if(matchMedia('(max-width:820px)').matches)$('control-panel').open=false;await preset('Eduardo Paes');await initRivals();}
init().catch(showError);
